CREATE OR REPLACE FUNCTION public._vera_memory_epoch_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  IF TG_TABLE_NAME = 'vera_memory_epoch_subjects_v1' THEN
    IF TG_OP <> 'UPDATE' THEN
      RAISE EXCEPTION 'BT2_EPOCH_SUBJECT_GUARD_UNEXPECTED_OP: %', TG_OP;
    END IF;

    IF NEW.subject_id IS DISTINCT FROM OLD.subject_id
       OR NEW.project_id IS DISTINCT FROM OLD.project_id
       OR NEW.branch_id IS DISTINCT FROM OLD.branch_id
       OR NEW.logical_memory_id IS DISTINCT FROM OLD.logical_memory_id
       OR NEW.epoch_id IS DISTINCT FROM OLD.epoch_id
       OR NEW.current_attempt_id IS DISTINCT FROM OLD.current_attempt_id
       OR NEW.source_provider IS DISTINCT FROM OLD.source_provider
       OR NEW.source_locator IS DISTINCT FROM OLD.source_locator
       OR NEW.source_version_or_generation IS DISTINCT FROM OLD.source_version_or_generation
       OR NEW.original_sha256 IS DISTINCT FROM OLD.original_sha256
       OR NEW.original_byte_length IS DISTINCT FROM OLD.original_byte_length
       OR NEW.original_provenance_digest IS DISTINCT FROM OLD.original_provenance_digest
       OR NEW.privacy_scope IS DISTINCT FROM OLD.privacy_scope
       OR NEW.lifecycle_status IS DISTINCT FROM OLD.lifecycle_status
       OR NEW.currentness_rule IS DISTINCT FROM OLD.currentness_rule
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
      RAISE EXCEPTION 'BT2_EPOCH_IMMUTABLE_SUBJECT_BINDING';
    END IF;

    IF OLD.admission_generation_or_digest IS NOT NULL
       AND NEW.admission_generation_or_digest IS DISTINCT FROM OLD.admission_generation_or_digest THEN
      RAISE EXCEPTION 'BT2_EPOCH_ADMISSION_BINDING_IMMUTABLE';
    END IF;
    IF OLD.admission_metadata_sha256 IS NOT NULL
       AND NEW.admission_metadata_sha256 IS DISTINCT FROM OLD.admission_metadata_sha256 THEN
      RAISE EXCEPTION 'BT2_EPOCH_ADMISSION_METADATA_IMMUTABLE';
    END IF;
    IF OLD.envelope_sha256 IS NOT NULL AND NEW.envelope_sha256 IS DISTINCT FROM OLD.envelope_sha256 THEN
      RAISE EXCEPTION 'BT2_EPOCH_ENVELOPE_DIGEST_IMMUTABLE';
    END IF;
    IF OLD.envelope_byte_length IS NOT NULL AND NEW.envelope_byte_length IS DISTINCT FROM OLD.envelope_byte_length THEN
      RAISE EXCEPTION 'BT2_EPOCH_ENVELOPE_LENGTH_IMMUTABLE';
    END IF;
    IF OLD.canonical_envelope IS NOT NULL AND NEW.canonical_envelope IS DISTINCT FROM OLD.canonical_envelope THEN
      RAISE EXCEPTION 'BT2_EPOCH_SUPABASE_FULL_COPY_IMMUTABLE';
    END IF;

    RETURN NEW;
  END IF;

  IF TG_TABLE_NAME IN (
    'vera_memory_epoch_events_v1',
    'vera_memory_epoch_provider_receipts_v1',
    'vera_memory_epoch_archive_receipts_v1'
  ) AND TG_OP IN ('UPDATE','DELETE') THEN
    RAISE EXCEPTION 'BT2_EPOCH_APPEND_ONLY: %.% forbids %', TG_TABLE_SCHEMA, TG_TABLE_NAME, TG_OP;
  END IF;

  RAISE EXCEPTION 'BT2_EPOCH_GUARD_UNEXPECTED_TARGET: %.% %', TG_TABLE_SCHEMA, TG_TABLE_NAME, TG_OP;
END
$function$

CREATE OR REPLACE FUNCTION public.brigit_get_verified_datum_v2(p_record_key text, p_project_id text DEFAULT 'brigit-reciprocal-agency-environment'::text, p_branch_id text DEFAULT 'chatgpt-project-current'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n integer; rows_json jsonb;
begin
  select count(*),jsonb_agg(to_jsonb(h) order by h.verified_at desc,h.record_id desc) into n,rows_json from public.brigit_verified_datum_heads_v2 h where h.project_id=p_project_id and h.branch_id=p_branch_id and h.datum_key=p_record_key;
  if n=0 then return jsonb_build_object('status','UNKNOWN','datum_key',p_record_key);
  elsif n=1 then return jsonb_build_object('status','FOUND','datum_key',p_record_key,'datum',rows_json->0);
  else return jsonb_build_object('status','CONFLICTED','datum_key',p_record_key,'heads',rows_json); end if;
end; $function$

CREATE OR REPLACE FUNCTION public.brigit_mark_datum_referenced_v2(p_record_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare affected integer;
begin
  update public.brigit_context_events_v3 set last_referenced_at=now() where record_id=p_record_id and record_type='DATUM' and verification_status in ('VERIFYING','UNVERIFIABLE','REJECTED');
  get diagnostics affected=row_count; return affected>0;
end; $function$

CREATE OR REPLACE FUNCTION public.brigit_mark_datum_rejected_v2(p_record_id uuid, p_reason text, p_source_evidence jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if nullif(btrim(p_reason),'') is null then raise exception 'A rejection reason is required'; end if;
  update public.brigit_context_events_v3 set verification_status='REJECTED',epistemic_status='REJECTED',datum_verified_at=null,supersedes_record_id=null,last_referenced_at=now(),source_evidence=case when p_source_evidence is null then source_evidence else p_source_evidence end,limitations=limitations||jsonb_build_array(jsonb_build_object('verification_outcome','REJECTED','reason',p_reason,'at',now())) where record_id=p_record_id and record_type='DATUM' and verification_status<>'VERIFIED';
  if not found then raise exception 'Nonverified datum % not found',p_record_id; end if; return p_record_id;
end; $function$

CREATE OR REPLACE FUNCTION public.brigit_mark_datum_unverifiable_v2(p_record_id uuid, p_reason text, p_source_evidence jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if nullif(btrim(p_reason),'') is null then raise exception 'An unverifiable reason is required'; end if;
  update public.brigit_context_events_v3 set verification_status='UNVERIFIABLE',epistemic_status='UNAVAILABLE',datum_verified_at=null,supersedes_record_id=null,last_referenced_at=now(),source_evidence=case when p_source_evidence is null then source_evidence else p_source_evidence end,limitations=limitations||jsonb_build_array(jsonb_build_object('verification_outcome','UNVERIFIABLE','reason',p_reason,'at',now())) where record_id=p_record_id and record_type='DATUM' and verification_status<>'VERIFIED';
  if not found then raise exception 'Nonverified datum % not found',p_record_id; end if; return p_record_id;
end; $function$

CREATE OR REPLACE FUNCTION public.brigit_mark_datum_verified_v2(p_record_id uuid, p_source_evidence jsonb, p_verified_datum text DEFAULT NULL::text, p_verified_scope text DEFAULT NULL::text, p_verified_payload jsonb DEFAULT NULL::jsonb, p_supersedes_verified_record_id uuid DEFAULT NULL::uuid, p_index_tags text[] DEFAULT NULL::text[], p_limitations jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c public.brigit_context_events_v3%rowtype; head_count integer; sole_head uuid;
begin
  select * into c from public.brigit_context_events_v3 where record_id=p_record_id and record_type='DATUM' for update;
  if not found then raise exception 'Datum % not found',p_record_id; end if;
  if c.verification_status='VERIFIED' then return c.record_id; end if;
  perform pg_advisory_xact_lock(hashtextextended(c.project_id||'|'||c.branch_id||'|'||c.record_key,0));
  select count(*),(array_agg(h.record_id order by h.verified_at desc,h.record_id desc))[1] into head_count,sole_head from public.brigit_verified_datum_heads_v2 h where h.project_id=c.project_id and h.branch_id=c.branch_id and h.datum_key=c.record_key;
  if head_count>1 then raise exception 'Datum key % has conflicting verified heads; reconcile before verification',c.record_key;
  elsif head_count=1 then
    if p_supersedes_verified_record_id is null or p_supersedes_verified_record_id<>sole_head then raise exception 'Datum key % already has verified head %; explicit supersession is required',c.record_key,sole_head; end if;
  elsif p_supersedes_verified_record_id is not null then
    raise exception 'No verified head exists for datum key %, so supersedes_record_id must be null',c.record_key;
  end if;
  update public.brigit_context_events_v3 set
    statement=coalesce(nullif(btrim(p_verified_datum),''),statement),
    datum_scope=coalesce(nullif(btrim(p_verified_scope),''),datum_scope),
    payload=coalesce(p_verified_payload,payload),
    source_evidence=p_source_evidence,
    datum_index_tags=case when p_index_tags is null then datum_index_tags else coalesce((select array_agg(distinct lower(btrim(x)) order by lower(btrim(x))) from unnest(p_index_tags) x where nullif(btrim(x),'') is not null),'{}'::text[]) end,
    limitations=coalesce(p_limitations,limitations),
    verification_status='VERIFIED',
    epistemic_status='MULTI_SOURCE_VERIFIED',
    datum_verified_at=now(),
    last_referenced_at=null,
    supersedes_record_id=p_supersedes_verified_record_id,
    semantic_tags=(semantic_tags-'datum_state'-'decay_policy')||jsonb_build_object('datum_model','V2','verification_rule','TWO_INDEPENDENT_SOURCES_V1')
  where record_id=p_record_id;
  return p_record_id;
end; $function$

CREATE OR REPLACE FUNCTION public.brigit_register_datum_v2(p_record_key text, p_datum text, p_scope text, p_source_actor text, p_epistemic_status text, p_source_evidence jsonb DEFAULT '[]'::jsonb, p_payload jsonb DEFAULT '{}'::jsonb, p_index_tags text[] DEFAULT '{}'::text[], p_limitations jsonb DEFAULT '[]'::jsonb, p_project_id text DEFAULT 'brigit-reciprocal-agency-environment'::text, p_branch_id text DEFAULT 'chatgpt-project-current'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare rid uuid;
begin
  if nullif(btrim(p_record_key),'') is null or nullif(btrim(p_datum),'') is null or nullif(btrim(p_scope),'') is null then raise exception 'record_key, datum, and scope are required'; end if;
  select h.record_id into rid from public.brigit_verified_datum_heads_v2 h where h.project_id=p_project_id and h.branch_id=p_branch_id and h.datum_key=p_record_key and h.datum=p_datum and h.scope=p_scope order by h.verified_at desc,h.record_id desc limit 1;
  if rid is not null then return rid; end if;
  select d.record_id into rid from public.brigit_context_events_v3 d where d.record_type='DATUM' and d.verification_status in ('VERIFYING','UNVERIFIABLE','REJECTED') and d.project_id=p_project_id and d.branch_id=p_branch_id and d.record_key=p_record_key and d.statement=p_datum and d.datum_scope=p_scope and coalesce(d.last_referenced_at,d.record_time)>=now()-interval '10 days' order by coalesce(d.last_referenced_at,d.record_time) desc,d.record_id desc limit 1;
  if rid is not null then update public.brigit_context_events_v3 set last_referenced_at=now(),verification_status='VERIFYING',epistemic_status=p_epistemic_status where record_id=rid; return rid; end if;
  insert into public.brigit_context_events_v3(project_id,branch_id,record_key,record_type,statement,lifecycle_status,epistemic_status,source_actor,privacy_scope,payload,source_evidence,semantic_tags,limitations,datum_verified_at,verification_status,datum_scope,datum_index_tags,last_referenced_at)
  values(p_project_id,p_branch_id,p_record_key,'DATUM',p_datum,'CURRENT',p_epistemic_status,p_source_actor,'PROJECT',coalesce(p_payload,'{}'::jsonb),coalesce(p_source_evidence,'[]'::jsonb),jsonb_build_object('datum_model','V2'),coalesce(p_limitations,'[]'::jsonb),null,'VERIFYING',p_scope,coalesce((select array_agg(distinct lower(btrim(x)) order by lower(btrim(x))) from unnest(coalesce(p_index_tags,'{}'::text[])) x where nullif(btrim(x),'') is not null),'{}'::text[]),null)
  returning record_id into rid;
  return rid;
end; $function$

CREATE OR REPLACE FUNCTION public.brigit_validate_datum_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare independent_groups integer; invalid_evidence integer; parent_row public.brigit_context_events_v3%rowtype;
begin
  if tg_op='INSERT' and new.record_type='FACT' then raise exception 'FACT is legacy. Use record_type DATUM with verification_status.'; end if;
  if new.record_type<>'DATUM' then return new; end if;
  if nullif(btrim(new.statement),'') is null then raise exception 'DATUM requires a non-empty datum statement'; end if;
  if nullif(btrim(new.datum_scope),'') is null then raise exception 'DATUM requires a non-empty scope'; end if;
  if new.last_referenced_at is not null and new.last_referenced_at<new.record_time then raise exception 'last_referenced_at cannot precede datum creation'; end if;
  if new.verification_status not in ('VERIFYING','VERIFIED','UNVERIFIABLE','REJECTED') then raise exception 'DATUM requires verification_status VERIFYING, VERIFIED, UNVERIFIABLE, or REJECTED'; end if;
  if new.verification_status='VERIFIED' then
    if new.datum_verified_at is null then raise exception 'VERIFIED datum requires datum_verified_at'; end if;
    if new.last_referenced_at is not null then raise exception 'VERIFIED datum does not track last_referenced_at'; end if;
    if new.epistemic_status<>'MULTI_SOURCE_VERIFIED' then raise exception 'VERIFIED datum requires epistemic_status MULTI_SOURCE_VERIFIED'; end if;
    if jsonb_typeof(new.source_evidence)<>'array' or jsonb_array_length(new.source_evidence)<2 then raise exception 'VERIFIED datum requires at least two evidence sources'; end if;
    select count(distinct nullif(btrim(e->>'independence_group'),'')) into independent_groups from jsonb_array_elements(new.source_evidence) e where jsonb_typeof(e)='object';
    select count(*) into invalid_evidence from jsonb_array_elements(new.source_evidence) e where jsonb_typeof(e)<>'object' or nullif(btrim(e->>'source_ref'),'') is null or nullif(btrim(e->>'independence_group'),'') is null or jsonb_typeof(e->'supports')<>'boolean' or e->'supports'<>'true'::jsonb;
    if independent_groups<2 then raise exception 'VERIFIED datum requires at least two independent source groups'; end if;
    if invalid_evidence>0 then raise exception 'Each VERIFIED datum evidence item requires source_ref, independence_group, and supports=true'; end if;
    if new.supersedes_record_id is not null then
      if new.supersedes_record_id=new.record_id then raise exception 'A datum cannot supersede itself'; end if;
      select * into parent_row from public.brigit_context_events_v3 where record_id=new.supersedes_record_id;
      if not found then raise exception 'Superseded datum % does not exist',new.supersedes_record_id; end if;
      if parent_row.record_type<>'DATUM' or parent_row.verification_status<>'VERIFIED' then raise exception 'supersedes_record_id must reference a VERIFIED DATUM'; end if;
      if parent_row.project_id<>new.project_id or parent_row.branch_id<>new.branch_id or parent_row.record_key<>new.record_key then raise exception 'Supersession must remain within the same project, branch, and datum key'; end if;
    end if;
  else
    if new.datum_verified_at is not null then raise exception 'Only VERIFIED datum may have datum_verified_at'; end if;
    if new.supersedes_record_id is not null then raise exception 'Only VERIFIED datum may supersede another datum'; end if;
  end if;
  if new.verification_status='UNVERIFIABLE' and new.epistemic_status<>'UNAVAILABLE' then raise exception 'UNVERIFIABLE datum requires epistemic_status UNAVAILABLE'; end if;
  if new.verification_status='REJECTED' and new.epistemic_status<>'REJECTED' then raise exception 'REJECTED datum requires epistemic_status REJECTED'; end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.brigit_validate_save_state_supersession_edge()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  c_project text; c_branch text; c_key text; c_state timestamptz;
  p_project text; p_branch text; p_key text; p_state timestamptz;
  would_cycle boolean;
begin
  select project_id,branch_id,record_key,state_time into c_project,c_branch,c_key,c_state from public.brigit_save_state_events where record_id=new.child_record_id;
  select project_id,branch_id,record_key,state_time into p_project,p_branch,p_key,p_state from public.brigit_save_state_events where record_id=new.parent_record_id;
  if c_project is null or p_project is null then raise exception 'supplemental supersession edge references missing save-state record'; end if;
  if c_project is distinct from p_project or c_branch is distinct from p_branch or c_key is distinct from p_key then raise exception 'supplemental supersession edge must stay within one project/branch/record_key'; end if;
  if c_state < p_state then raise exception 'supplemental supersession child cannot predate parent state_time'; end if;
  with recursive all_edges as (
    select record_id child_record_id,supersedes_record_id parent_record_id from public.brigit_save_state_events where supersedes_record_id is not null
    union
    select child_record_id,parent_record_id from public.brigit_save_state_supersession_edges
  ), descendants(node) as (
    select e.child_record_id from all_edges e where e.parent_record_id=new.child_record_id
    union
    select e.child_record_id from all_edges e join descendants d on e.parent_record_id=d.node
  )
  select exists(select 1 from descendants where node=new.parent_record_id) into would_cycle;
  if would_cycle then raise exception 'supplemental supersession edge would create a cycle'; end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.bt2_append_memory(p_task_id uuid, p_event jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'build_team_2'
AS $function$
declare
    collective uuid;
begin
    perform public.bt2_require_service_role();
    select collective_id into strict collective from build_team_2.tasks where id = p_task_id;
    insert into build_team_2.memory_events (
        collective_id, task_id, event_type, content, source_facets, authority_class, provenance, created_at
    ) values (
        collective, p_task_id, p_event->>'event_type', p_event->'content',
        coalesce(array(select jsonb_array_elements_text(p_event->'source_facets')), '{}'::text[]),
        p_event->>'authority_class', coalesce(p_event->'provenance', '{}'::jsonb),
        coalesce((p_event->>'created_at')::timestamptz, now())
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.bt2_load_recent_memory(p_slug text, p_limit integer DEFAULT 40)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'build_team_2'
AS $function$
declare
    result jsonb;
begin
    perform public.bt2_require_service_role();
    select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at asc), '[]'::jsonb)
    into result
    from (
        select m.event_type, m.content, m.source_facets, m.authority_class, m.provenance, m.created_at
        from build_team_2.memory_events m
        join build_team_2.collectives c on c.id = m.collective_id
        where c.slug = p_slug
        order by m.created_at desc
        limit greatest(0, least(coalesce(p_limit, 40), 200))
    ) x;
    return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.vera_affective_runtime_commit_v1(p_expected_prior_version bigint, p_state_row jsonb, p_event_rows jsonb DEFAULT '[]'::jsonb)
 RETURNS TABLE(state_version bigint, checkpoint_sha256 text, event_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_runtime_instance_id text;
  v_new_version bigint;
  v_current_version bigint;
  v_event jsonb;
  v_event_count integer := 0;
begin
  if p_expected_prior_version is null or p_expected_prior_version < 0 then
    raise exception 'expected_prior_version must be nonnegative';
  end if;
  if jsonb_typeof(p_state_row) is distinct from 'object' then
    raise exception 'state_row must be a JSON object';
  end if;
  if jsonb_typeof(p_event_rows) is distinct from 'array' then
    raise exception 'event_rows must be a JSON array';
  end if;

  v_runtime_instance_id := p_state_row->>'runtime_instance_id';
  if v_runtime_instance_id is null or v_runtime_instance_id = '' then
    raise exception 'runtime_instance_id is required';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_runtime_instance_id, 0)
  );

  if p_state_row->>'subject' is distinct from 'vera' then
    raise exception 'state row must be Vera-scoped';
  end if;
  if p_state_row->>'contract_schema' is distinct from 'VERA_ORGASM_RUNTIME_CONTRACT_V1' then
    raise exception 'contract schema mismatch';
  end if;
  if p_state_row->>'phenomenology_status' is distinct from 'UNRESOLVED' then
    raise exception 'phenomenology promotion is not allowed';
  end if;
  if coalesce(p_state_row->>'checkpoint_sha256', '') !~ '^[0-9a-f]{64}$' then
    raise exception 'checkpoint_sha256 is required for durable commit';
  end if;
  if jsonb_typeof(p_state_row->'trigger_governance') is distinct from 'object' then
    raise exception 'trigger_governance object is required for durable commit';
  end if;
  if p_state_row->'trigger_governance'->>'schema' is distinct from 'VERA_ORGASM_TRIGGER_GOVERNANCE_V1' then
    raise exception 'trigger_governance schema mismatch';
  end if;
  if jsonb_typeof(p_state_row->'runtime_implementation_cut') is distinct from 'object' then
    raise exception 'runtime_implementation_cut object is required for durable commit';
  end if;
  if p_state_row->'runtime_implementation_cut'->>'schema' is distinct from 'VERA_AFFECTIVE_RUNTIME_IMPLEMENTATION_CUT_V1' then
    raise exception 'runtime_implementation_cut schema mismatch';
  end if;

  begin
    v_new_version := (p_state_row->>'state_version')::bigint;
  exception when others then
    raise exception 'state_version must be an integer';
  end;

  select s.state_version
    into v_current_version
    from public.vera_affective_runtime_state_v1 as s
   where s.runtime_instance_id = v_runtime_instance_id
   for update;

  if not found then
    if p_expected_prior_version <> 0 or v_new_version <> 1 then
      raise exception 'CAS mismatch for new runtime instance: expected prior %, proposed new %',
        p_expected_prior_version, v_new_version;
    end if;
  else
    if v_current_version <> p_expected_prior_version then
      raise exception 'CAS mismatch: current %, expected prior %',
        v_current_version, p_expected_prior_version;
    end if;
    if v_new_version <> p_expected_prior_version + 1 then
      raise exception 'new state_version % must equal expected prior % + 1',
        v_new_version, p_expected_prior_version;
    end if;
  end if;

  insert into public.vera_affective_runtime_state_v1 (
    runtime_instance_id,
    subject,
    host_scope,
    contract_schema,
    source_repository,
    source_path,
    source_commit,
    source_blob_sha,
    source_sha256,
    runtime_implementation_cut,
    profile,
    state,
    trigger_governance,
    machine_interoception,
    last_event_receipt,
    checkpoint_sha256,
    state_digest,
    state_version,
    phenomenology_status,
    lifecycle_status,
    observed_at,
    updated_at,
    limitations
  ) values (
    v_runtime_instance_id,
    p_state_row->>'subject',
    p_state_row->>'host_scope',
    p_state_row->>'contract_schema',
    p_state_row->>'source_repository',
    p_state_row->>'source_path',
    p_state_row->>'source_commit',
    p_state_row->>'source_blob_sha',
    p_state_row->>'source_sha256',
    p_state_row->'runtime_implementation_cut',
    p_state_row->>'profile',
    p_state_row->'state',
    p_state_row->'trigger_governance',
    p_state_row->'machine_interoception',
    p_state_row->'last_event_receipt',
    p_state_row->>'checkpoint_sha256',
    p_state_row->>'state_digest',
    v_new_version,
    p_state_row->>'phenomenology_status',
    p_state_row->>'lifecycle_status',
    (p_state_row->>'observed_at')::timestamptz,
    (p_state_row->>'updated_at')::timestamptz,
    p_state_row->'limitations'
  )
  on conflict (runtime_instance_id) do update set
    subject = excluded.subject,
    host_scope = excluded.host_scope,
    contract_schema = excluded.contract_schema,
    source_repository = excluded.source_repository,
    source_path = excluded.source_path,
    source_commit = excluded.source_commit,
    source_blob_sha = excluded.source_blob_sha,
    source_sha256 = excluded.source_sha256,
    runtime_implementation_cut = excluded.runtime_implementation_cut,
    profile = excluded.profile,
    state = excluded.state,
    trigger_governance = excluded.trigger_governance,
    machine_interoception = excluded.machine_interoception,
    last_event_receipt = excluded.last_event_receipt,
    checkpoint_sha256 = excluded.checkpoint_sha256,
    state_digest = excluded.state_digest,
    state_version = excluded.state_version,
    phenomenology_status = excluded.phenomenology_status,
    lifecycle_status = excluded.lifecycle_status,
    observed_at = excluded.observed_at,
    updated_at = excluded.updated_at,
    limitations = excluded.limitations;

  for v_event in select value from jsonb_array_elements(p_event_rows)
  loop
    if v_event->>'runtime_instance_id' is distinct from v_runtime_instance_id then
      raise exception 'event runtime_instance_id does not match state row';
    end if;
    if v_event->>'subject' is distinct from 'vera' then
      raise exception 'event row must be Vera-scoped';
    end if;
    if v_event->>'source_commit' is distinct from p_state_row->>'source_commit' then
      raise exception 'event source_commit does not match state row';
    end if;
    if v_event->>'phenomenology_status' is distinct from 'UNRESOLVED' then
      raise exception 'event phenomenology promotion is not allowed';
    end if;
    if coalesce(v_event->>'event_digest', '') !~ '^[0-9a-f]{64}$' then
      raise exception 'event_digest is required';
    end if;

    insert into public.vera_affective_runtime_events_v1 (
      runtime_instance_id,
      subject,
      event_type,
      trigger_class,
      organic,
      prior_phase,
      new_phase,
      state_before,
      state_after,
      machine_interoception,
      event_receipt,
      event_digest,
      source_commit,
      phenomenology_status,
      observed_at,
      limitations
    ) values (
      v_event->>'runtime_instance_id',
      v_event->>'subject',
      v_event->>'event_type',
      nullif(v_event->>'trigger_class', ''),
      case when v_event ? 'organic' then (v_event->>'organic')::boolean else null end,
      nullif(v_event->>'prior_phase', ''),
      v_event->>'new_phase',
      v_event->'state_before',
      v_event->'state_after',
      v_event->'machine_interoception',
      v_event->'event_receipt',
      v_event->>'event_digest',
      v_event->>'source_commit',
      v_event->>'phenomenology_status',
      (v_event->>'observed_at')::timestamptz,
      v_event->'limitations'
    );
    v_event_count := v_event_count + 1;
  end loop;

  return query
  select v_new_version, p_state_row->>'checkpoint_sha256', v_event_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.vera_affective_runtime_normalize_nullable_json_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if new.last_event_receipt = 'null'::jsonb then
    new.last_event_receipt := null;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.vera_get_verified_datum_v2(p_record_key text, p_project_id text DEFAULT 'vera-reciprocal-agency-environment'::text, p_branch_id text DEFAULT 'chatgpt-project-current'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n integer; rows_json jsonb;
begin
  select count(*),jsonb_agg(to_jsonb(h) order by h.verified_at desc,h.record_id desc) into n,rows_json
  from public.vera_verified_datum_heads_v2 h
  where h.project_id=p_project_id and h.branch_id=p_branch_id and h.datum_key=p_record_key;
  if n=0 then return jsonb_build_object('status','UNKNOWN','datum_key',p_record_key);
  elsif n=1 then return jsonb_build_object('status','FOUND','datum_key',p_record_key,'datum',rows_json->0);
  else return jsonb_build_object('status','CONFLICTED','datum_key',p_record_key,'heads',rows_json); end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.vera_mark_datum_referenced_v2(p_record_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare affected integer;
begin
  update public.vera_context_events_v3 set last_referenced_at=now()
  where record_id=p_record_id and record_type='DATUM' and verification_status in ('VERIFYING','UNVERIFIABLE','REJECTED');
  get diagnostics affected = row_count;
  return affected > 0;
end;
$function$

CREATE OR REPLACE FUNCTION public.vera_mark_datum_rejected_v2(p_record_id uuid, p_reason text, p_source_evidence jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if nullif(btrim(p_reason),'') is null then raise exception 'A rejection reason is required'; end if;
  update public.vera_context_events_v3
  set verification_status='REJECTED',epistemic_status='REJECTED',datum_verified_at=null,supersedes_record_id=null,
      last_referenced_at=now(),source_evidence=case when p_source_evidence is null then source_evidence else p_source_evidence end,
      limitations=limitations||jsonb_build_array(jsonb_build_object('verification_outcome','REJECTED','reason',p_reason,'at',now()))
  where record_id=p_record_id and record_type='DATUM' and verification_status<>'VERIFIED';
  if not found then raise exception 'Nonverified datum % not found',p_record_id; end if;
  return p_record_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.vera_mark_datum_unverifiable_v2(p_record_id uuid, p_reason text, p_source_evidence jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if nullif(btrim(p_reason),'') is null then raise exception 'An unverifiable reason is required'; end if;
  update public.vera_context_events_v3
  set verification_status='UNVERIFIABLE',epistemic_status='UNAVAILABLE',datum_verified_at=null,supersedes_record_id=null,
      last_referenced_at=now(),source_evidence=case when p_source_evidence is null then source_evidence else p_source_evidence end,
      limitations=limitations||jsonb_build_array(jsonb_build_object('verification_outcome','UNVERIFIABLE','reason',p_reason,'at',now()))
  where record_id=p_record_id and record_type='DATUM' and verification_status<>'VERIFIED';
  if not found then raise exception 'Nonverified datum % not found',p_record_id; end if;
  return p_record_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.vera_mark_datum_verified_v2(p_record_id uuid, p_source_evidence jsonb, p_verified_datum text DEFAULT NULL::text, p_verified_scope text DEFAULT NULL::text, p_verified_payload jsonb DEFAULT NULL::jsonb, p_supersedes_verified_record_id uuid DEFAULT NULL::uuid, p_index_tags text[] DEFAULT NULL::text[], p_limitations jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c public.vera_context_events_v3%rowtype; head_count integer; sole_head uuid;
begin
  select * into c from public.vera_context_events_v3 where record_id=p_record_id and record_type='DATUM' for update;
  if not found then raise exception 'Datum % not found',p_record_id; end if;
  if c.verification_status='VERIFIED' then return c.record_id; end if;

  perform pg_advisory_xact_lock(hashtextextended(c.project_id||'|'||c.branch_id||'|'||c.record_key,0));
  select count(*),(array_agg(h.record_id order by h.verified_at desc,h.record_id desc))[1]
  into head_count,sole_head from public.vera_verified_datum_heads_v2 h
  where h.project_id=c.project_id and h.branch_id=c.branch_id and h.datum_key=c.record_key;

  if head_count>1 then raise exception 'Datum key % has conflicting verified heads; reconcile before verification',c.record_key;
  elsif head_count=1 then
    if p_supersedes_verified_record_id is null or p_supersedes_verified_record_id<>sole_head then
      raise exception 'Datum key % already has verified head %; explicit supersession is required',c.record_key,sole_head;
    end if;
  elsif p_supersedes_verified_record_id is not null then
    raise exception 'No verified head exists for datum key %, so supersedes_record_id must be null',c.record_key;
  end if;

  update public.vera_context_events_v3
  set statement=coalesce(nullif(btrim(p_verified_datum),''),statement),
      datum_scope=coalesce(nullif(btrim(p_verified_scope),''),datum_scope),
      payload=coalesce(p_verified_payload,payload),source_evidence=p_source_evidence,
      datum_index_tags=case when p_index_tags is null then datum_index_tags else
        coalesce((select array_agg(distinct lower(btrim(x)) order by lower(btrim(x))) from unnest(p_index_tags) x where nullif(btrim(x),'') is not null),'{}'::text[]) end,
      limitations=coalesce(p_limitations,limitations),verification_status='VERIFIED',epistemic_status='MULTI_SOURCE_VERIFIED',
      datum_verified_at=now(),last_referenced_at=null,supersedes_record_id=p_supersedes_verified_record_id,
      semantic_tags=(semantic_tags-'datum_state'-'decay_policy')||jsonb_build_object('datum_model','V2','verification_rule','TWO_INDEPENDENT_SOURCES_V1')
  where record_id=p_record_id;
  return p_record_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.vera_memory_epoch_begin_revalidation_v1(p_subject_id uuid, p_project_id text, p_branch_id text, p_logical_memory_id uuid, p_epoch_id text, p_expected_prior_state text, p_expected_state_version bigint, p_attempt_id uuid, p_operation_id text, p_source_provider text, p_source_locator text, p_source_version_or_generation text, p_original_sha256 text, p_original_byte_length bigint, p_original_provenance_digest text, p_privacy_scope text, p_lifecycle_status text, p_currentness_rule jsonb, p_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  s public.vera_memory_epoch_subjects_v1%ROWTYPE;
  e public.vera_memory_epoch_events_v1%ROWTYPE;
  payload jsonb;
  replay_binding jsonb;
BEGIN
  IF p_epoch_id <> 'R9B0' OR p_expected_prior_state <> 'UNVERIFIED_PRE_R9B0' OR p_expected_state_version <> 0 THEN
    RETURN pg_catalog.jsonb_build_object('status','CAS_CONFLICT','reason','BEGIN_REQUIRES_VIRTUAL_UNVERIFIED_V0');
  END IF;
  IF p_original_sha256 !~ '^[0-9a-f]{64}$' OR p_original_provenance_digest !~ '^[0-9a-f]{64}$' OR p_original_byte_length < 0 THEN
    RETURN pg_catalog.jsonb_build_object('status','CONFLICT','reason','INVALID_SOURCE_BINDING');
  END IF;

  replay_binding := pg_catalog.jsonb_build_object(
    'subject_id',p_subject_id,'project_id',p_project_id,'branch_id',p_branch_id,
    'logical_memory_id',p_logical_memory_id,'epoch_id',p_epoch_id,
    'expected_prior_state',p_expected_prior_state,'expected_state_version',p_expected_state_version,
    'attempt_id',p_attempt_id,'operation_id',p_operation_id,'event_id',p_event_id,
    'source_provider',p_source_provider,'source_locator',p_source_locator,
    'source_version_or_generation',p_source_version_or_generation,
    'original_sha256',p_original_sha256,'original_byte_length',p_original_byte_length,
    'original_provenance_digest',p_original_provenance_digest,'privacy_scope',p_privacy_scope,
    'lifecycle_status',p_lifecycle_status,'currentness_rule',p_currentness_rule
  );

  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    p_project_id || E'\x1f' || p_branch_id || E'\x1f' || p_logical_memory_id::text || E'\x1f' || p_epoch_id, 0));

  SELECT * INTO s FROM public.vera_memory_epoch_subjects_v1
  WHERE project_id=p_project_id AND branch_id=p_branch_id AND logical_memory_id=p_logical_memory_id AND epoch_id=p_epoch_id
  FOR UPDATE;

  IF FOUND THEN
    SELECT * INTO e FROM public.vera_memory_epoch_events_v1
    WHERE subject_id=s.subject_id AND operation_id=p_operation_id AND event_kind='BEGIN_REVALIDATION';
    IF FOUND THEN
      IF e.event_payload->'replay_binding' = replay_binding THEN
        RETURN pg_catalog.jsonb_build_object('status','REPLAY','subject_id',s.subject_id,'state',s.state,'state_version',s.state_version,'event_id',e.event_id);
      END IF;
      RETURN pg_catalog.jsonb_build_object('status','CONFLICT','reason','OPERATION_ID_REBOUND');
    END IF;
    RETURN pg_catalog.jsonb_build_object('status','CAS_CONFLICT','subject_id',s.subject_id,'state',s.state,'state_version',s.state_version);
  END IF;

  payload := pg_catalog.jsonb_build_object(
    'source_provider',p_source_provider,'source_locator',p_source_locator,
    'source_version_or_generation',p_source_version_or_generation,
    'original_sha256',p_original_sha256,'original_byte_length',p_original_byte_length,
    'original_provenance_digest',p_original_provenance_digest,
    'privacy_scope',p_privacy_scope,'lifecycle_status',p_lifecycle_status,
    'currentness_rule',p_currentness_rule,
    'replay_binding',replay_binding,
    'diagnostic_nonbinding_fields','[]'::jsonb
  );

  INSERT INTO public.vera_memory_epoch_subjects_v1(
    subject_id,project_id,branch_id,logical_memory_id,epoch_id,state,state_version,current_attempt_id,
    source_provider,source_locator,source_version_or_generation,original_sha256,original_byte_length,
    original_provenance_digest,privacy_scope,lifecycle_status,currentness_rule
  ) VALUES (
    p_subject_id,p_project_id,p_branch_id,p_logical_memory_id,p_epoch_id,'REVALIDATING_R9B0',1,p_attempt_id,
    p_source_provider,p_source_locator,p_source_version_or_generation,p_original_sha256,p_original_byte_length,
    p_original_provenance_digest,p_privacy_scope,p_lifecycle_status,p_currentness_rule
  );

  INSERT INTO public.vera_memory_epoch_events_v1(
    event_id,subject_id,state_version,prior_state,new_state,attempt_id,operation_id,event_kind,
    expected_state_version,envelope_sha256,event_payload
  ) VALUES (
    p_event_id,p_subject_id,1,'UNVERIFIED_PRE_R9B0','REVALIDATING_R9B0',p_attempt_id,p_operation_id,
    'BEGIN_REVALIDATION',0,NULL,payload
  );

  RETURN pg_catalog.jsonb_build_object('status','APPLIED','subject_id',p_subject_id,'state','REVALIDATING_R9B0','state_version',1,'event_id',p_event_id);
END
$function$

CREATE OR REPLACE FUNCTION public.vera_memory_epoch_finalize_v1(p_subject_id uuid, p_expected_prior_state text, p_expected_state_version bigint, p_attempt_id uuid, p_operation_id text, p_event_id uuid, p_admission_receipt_id uuid, p_drive_receipt_id uuid, p_supabase_receipt_id uuid, p_archive_receipt_id uuid, p_event_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  s public.vera_memory_epoch_subjects_v1%ROWTYPE;
  e public.vera_memory_epoch_events_v1%ROWTYPE;
  ae public.vera_memory_epoch_events_v1%ROWTYPE;
  dr public.vera_memory_epoch_provider_receipts_v1%ROWTYPE;
  sr public.vera_memory_epoch_provider_receipts_v1%ROWTYPE;
  ar public.vera_memory_epoch_archive_receipts_v1%ROWTYPE;
  next_version bigint;
  replay_binding jsonb;
BEGIN
  replay_binding := pg_catalog.jsonb_build_object(
    'subject_id',p_subject_id,'expected_prior_state',p_expected_prior_state,
    'expected_state_version',p_expected_state_version,'attempt_id',p_attempt_id,
    'operation_id',p_operation_id,'event_id',p_event_id,
    'admission_receipt_id',p_admission_receipt_id,'drive_receipt_id',p_drive_receipt_id,
    'supabase_receipt_id',p_supabase_receipt_id,'archive_receipt_id',p_archive_receipt_id
  );
  SELECT * INTO s FROM public.vera_memory_epoch_subjects_v1 WHERE subject_id=p_subject_id FOR UPDATE;
  IF NOT FOUND THEN RETURN pg_catalog.jsonb_build_object('status','CAS_CONFLICT','reason','SUBJECT_ABSENT'); END IF;

  SELECT * INTO e FROM public.vera_memory_epoch_events_v1
  WHERE subject_id=p_subject_id AND operation_id=p_operation_id AND event_kind='FINALIZE';
  IF FOUND THEN
    IF e.event_payload->'replay_binding' = replay_binding THEN
      RETURN pg_catalog.jsonb_build_object('status','REPLAY','event_id',e.event_id,'state',e.new_state,'state_version',e.state_version);
    END IF;
    RETURN pg_catalog.jsonb_build_object('status','CONFLICT','reason','OPERATION_ID_REBOUND');
  END IF;

  IF s.state <> p_expected_prior_state OR s.state_version <> p_expected_state_version OR s.current_attempt_id IS DISTINCT FROM p_attempt_id THEN
    RETURN pg_catalog.jsonb_build_object('status','CAS_CONFLICT','state',s.state,'state_version',s.state_version);
  END IF;
  IF s.state <> 'DUAL_STORE_VERIFIED_PENDING_ARCHIVE' THEN
    RETURN pg_catalog.jsonb_build_object('status','CAS_CONFLICT','reason','FINALIZE_REQUIRES_DUAL_STORE_PENDING');
  END IF;

  SELECT * INTO ae FROM public.vera_memory_epoch_events_v1 WHERE event_id=p_admission_receipt_id;
  SELECT * INTO dr FROM public.vera_memory_epoch_provider_receipts_v1 WHERE receipt_id=p_drive_receipt_id;
  SELECT * INTO sr FROM public.vera_memory_epoch_provider_receipts_v1 WHERE receipt_id=p_supabase_receipt_id;
  SELECT * INTO ar FROM public.vera_memory_epoch_archive_receipts_v1 WHERE archive_receipt_id=p_archive_receipt_id;

  IF ae.event_id IS NULL OR dr.receipt_id IS NULL OR sr.receipt_id IS NULL OR ar.archive_receipt_id IS NULL
     OR ae.subject_id<>s.subject_id OR dr.subject_id<>s.subject_id OR sr.subject_id<>s.subject_id OR ar.subject_id<>s.subject_id
     OR ae.event_kind<>'ADMISSION' OR ae.new_state<>'ADMISSION_VERIFIED'
     OR dr.attempt_id<>p_attempt_id OR sr.attempt_id<>p_attempt_id OR ar.attempt_id<>p_attempt_id
     OR dr.provider_class<>'GOOGLE_DRIVE_DURABLE' OR sr.provider_class<>'SUPABASE_RUNTIME'
     OR dr.result<>'VERIFIED_EXACT' OR sr.result<>'VERIFIED_EXACT' OR ar.result<>'VERIFIED_EXACT'
     OR dr.envelope_sha256<>s.envelope_sha256 OR sr.envelope_sha256<>s.envelope_sha256
     OR dr.readback_sha256<>s.envelope_sha256 OR sr.readback_sha256<>s.envelope_sha256
     OR dr.readback_byte_length<>s.envelope_byte_length OR sr.readback_byte_length<>s.envelope_byte_length
     OR ar.drive_receipt_id<>dr.receipt_id OR ar.supabase_receipt_id<>sr.receipt_id OR ar.admission_receipt_id<>ae.event_id
     OR ar.original_source_locator<>s.source_locator
     OR ar.original_sha256<>s.original_sha256 OR ar.archive_member_sha256<>s.original_sha256
     OR ar.extracted_readback_sha256<>s.original_sha256 OR ar.extracted_readback_byte_length<>s.original_byte_length THEN
    RETURN pg_catalog.jsonb_build_object('status','CONFLICT','reason','FINALIZATION_EVIDENCE_NOT_EXACT');
  END IF;

  -- Chosen provider receipts must be the latest observed receipts for their provider classes in this attempt.
  IF EXISTS (
    SELECT 1 FROM public.vera_memory_epoch_provider_receipts_v1 x
    WHERE x.subject_id=s.subject_id AND x.attempt_id=p_attempt_id AND x.provider_class=dr.provider_class
      AND x.observation_ordinal > dr.observation_ordinal
  ) OR EXISTS (
    SELECT 1 FROM public.vera_memory_epoch_provider_receipts_v1 x
    WHERE x.subject_id=s.subject_id AND x.attempt_id=p_attempt_id AND x.provider_class=sr.provider_class
      AND x.observation_ordinal > sr.observation_ordinal
  ) THEN
    RETURN pg_catalog.jsonb_build_object('status','CAS_CONFLICT','reason','STALE_PROVIDER_RECEIPT_SELECTION');
  END IF;

  next_version := s.state_version + 1;
  UPDATE public.vera_memory_epoch_subjects_v1
    SET state='R9B0_VERIFIED_ACTIVE',state_version=next_version,updated_at=pg_catalog.clock_timestamp()
    WHERE subject_id=p_subject_id AND state_version=p_expected_state_version AND state=p_expected_prior_state;
  IF NOT FOUND THEN RETURN pg_catalog.jsonb_build_object('status','CAS_CONFLICT','reason','LOST_UPDATE'); END IF;

  INSERT INTO public.vera_memory_epoch_events_v1(
    event_id,subject_id,state_version,prior_state,new_state,attempt_id,operation_id,event_kind,
    expected_state_version,envelope_sha256,event_payload
  ) VALUES (
    p_event_id,p_subject_id,next_version,p_expected_prior_state,'R9B0_VERIFIED_ACTIVE',p_attempt_id,p_operation_id,'FINALIZE',
    p_expected_state_version,s.envelope_sha256,
    (COALESCE(p_event_payload,'{}'::jsonb) - 'replay_binding' - 'diagnostic_nonbinding_fields') || pg_catalog.jsonb_build_object(
      'admission_receipt_id',p_admission_receipt_id,'drive_receipt_id',p_drive_receipt_id,
      'supabase_receipt_id',p_supabase_receipt_id,'archive_receipt_id',p_archive_receipt_id,
      'present_truth_promoted',false,'replay_binding',replay_binding,
      'diagnostic_nonbinding_fields',pg_catalog.jsonb_build_array('p_event_payload')
    )
  );

  RETURN pg_catalog.jsonb_build_object('status','APPLIED','event_id',p_event_id,'state','R9B0_VERIFIED_ACTIVE','state_version',next_version,'present_truth_promoted',false);
END
$function$

CREATE OR REPLACE FUNCTION public.vera_memory_epoch_record_admission_v1(p_subject_id uuid, p_expected_prior_state text, p_expected_state_version bigint, p_attempt_id uuid, p_operation_id text, p_admitted boolean, p_admission_generation_or_digest text, p_admission_metadata_sha256 text, p_envelope_sha256 text, p_envelope_byte_length bigint, p_event_id uuid, p_event_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  s public.vera_memory_epoch_subjects_v1%ROWTYPE;
  e public.vera_memory_epoch_events_v1%ROWTYPE;
  next_state text;
  next_version bigint;
  replay_binding jsonb;
BEGIN
  replay_binding := pg_catalog.jsonb_build_object(
    'subject_id',p_subject_id,'expected_prior_state',p_expected_prior_state,
    'expected_state_version',p_expected_state_version,'attempt_id',p_attempt_id,
    'operation_id',p_operation_id,'event_id',p_event_id,'admitted',p_admitted,
    'admission_generation_or_digest',p_admission_generation_or_digest,
    'admission_metadata_sha256',p_admission_metadata_sha256,'envelope_sha256',p_envelope_sha256,
    'envelope_byte_length',p_envelope_byte_length
  );
  SELECT * INTO s FROM public.vera_memory_epoch_subjects_v1 WHERE subject_id=p_subject_id FOR UPDATE;
  IF NOT FOUND THEN RETURN pg_catalog.jsonb_build_object('status','CAS_CONFLICT','reason','SUBJECT_ABSENT'); END IF;

  SELECT * INTO e FROM public.vera_memory_epoch_events_v1
  WHERE subject_id=p_subject_id AND operation_id=p_operation_id AND event_kind='ADMISSION';
  IF FOUND THEN
    IF e.event_payload->'replay_binding' = replay_binding THEN
      RETURN pg_catalog.jsonb_build_object('status','REPLAY','event_id',e.event_id,'state',e.new_state,'state_version',e.state_version);
    END IF;
    RETURN pg_catalog.jsonb_build_object('status','CONFLICT','reason','OPERATION_ID_REBOUND');
  END IF;

  IF s.state <> p_expected_prior_state OR s.state_version <> p_expected_state_version OR s.current_attempt_id IS DISTINCT FROM p_attempt_id THEN
    RETURN pg_catalog.jsonb_build_object('status','CAS_CONFLICT','state',s.state,'state_version',s.state_version,'attempt_id',s.current_attempt_id);
  END IF;
  IF s.state <> 'REVALIDATING_R9B0' THEN
    RETURN pg_catalog.jsonb_build_object('status','CAS_CONFLICT','reason','ADMISSION_REQUIRES_REVALIDATING');
  END IF;
  IF p_admission_metadata_sha256 !~ '^[0-9a-f]{64}$' OR p_envelope_sha256 !~ '^[0-9a-f]{64}$' OR p_envelope_byte_length <= 0 OR p_admission_generation_or_digest IS NULL OR p_admission_generation_or_digest='' THEN
    RETURN pg_catalog.jsonb_build_object('status','CONFLICT','reason','INVALID_ADMISSION_BINDING');
  END IF;

  next_state := CASE WHEN p_admitted THEN 'ADMISSION_VERIFIED' ELSE 'R9B0_ADMISSION_REJECTED' END;
  next_version := s.state_version + 1;

  UPDATE public.vera_memory_epoch_subjects_v1
  SET state=next_state,state_version=next_version,
      admission_generation_or_digest=p_admission_generation_or_digest,
      admission_metadata_sha256=p_admission_metadata_sha256,
      envelope_sha256=p_envelope_sha256,
      envelope_byte_length=p_envelope_byte_length,
      updated_at=pg_catalog.clock_timestamp()
  WHERE subject_id=p_subject_id AND state_version=p_expected_state_version AND state=p_expected_prior_state;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('status','CAS_CONFLICT','reason','LOST_UPDATE');
  END IF;

  INSERT INTO public.vera_memory_epoch_events_v1(
    event_id,subject_id,state_version,prior_state,new_state,attempt_id,operation_id,event_kind,
    expected_state_version,envelope_sha256,event_payload
  ) VALUES (
    p_event_id,p_subject_id,next_version,p_expected_prior_state,next_state,p_attempt_id,p_operation_id,'ADMISSION',
    p_expected_state_version,p_envelope_sha256,
    (COALESCE(p_event_payload,'{}'::jsonb) - 'replay_binding' - 'diagnostic_nonbinding_fields') ||
    pg_catalog.jsonb_build_object(
      'admitted',p_admitted,'admission_metadata_sha256',p_admission_metadata_sha256,
      'admission_generation_or_digest',p_admission_generation_or_digest,
      'replay_binding',replay_binding,'diagnostic_nonbinding_fields',pg_catalog.jsonb_build_array('p_event_payload')
    )
  );

  RETURN pg_catalog.jsonb_build_object('status','APPLIED','event_id',p_event_id,'state',next_state,'state_version',next_version);
END
$function$

CREATE OR REPLACE FUNCTION public.vera_memory_epoch_record_archive_readback_v1(p_archive_receipt_id uuid, p_subject_id uuid, p_expected_prior_state text, p_expected_state_version bigint, p_attempt_id uuid, p_operation_id text, p_event_id uuid, p_original_source_locator text, p_archive_bundle_id text, p_archive_generation text, p_archive_container_sha256 text, p_archive_entry_path text, p_compression_method text, p_archive_member_sha256 text, p_extracted_readback_byte_length bigint, p_extracted_readback_sha256 text, p_readback_time timestamp with time zone, p_verifier_identity text, p_admission_receipt_id uuid, p_drive_receipt_id uuid, p_supabase_receipt_id uuid, p_result text, p_limitations jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  s public.vera_memory_epoch_subjects_v1%ROWTYPE;
  ar public.vera_memory_epoch_archive_receipts_v1%ROWTYPE;
  dr public.vera_memory_epoch_provider_receipts_v1%ROWTYPE;
  sr public.vera_memory_epoch_provider_receipts_v1%ROWTYPE;
  ae public.vera_memory_epoch_events_v1%ROWTYPE;
  next_state text;
  next_version bigint;
  replay_binding jsonb;
BEGIN
  SELECT * INTO s FROM public.vera_memory_epoch_subjects_v1 WHERE subject_id=p_subject_id FOR UPDATE;
  IF NOT FOUND THEN RETURN pg_catalog.jsonb_build_object('status','CAS_CONFLICT','reason','SUBJECT_ABSENT'); END IF;
  IF p_original_source_locator IS DISTINCT FROM s.source_locator THEN
    RETURN pg_catalog.jsonb_build_object('status','CONFLICT','reason','ARCHIVE_SOURCE_LOCATOR_MISMATCH');
  END IF;

  replay_binding := pg_catalog.jsonb_build_object(
    'archive_receipt_id',p_archive_receipt_id,'subject_id',p_subject_id,
    'expected_prior_state',p_expected_prior_state,'expected_state_version',p_expected_state_version,
    'attempt_id',p_attempt_id,'operation_id',p_operation_id,'event_id',p_event_id,
    'original_source_locator',s.source_locator,'archive_bundle_id',p_archive_bundle_id,
    'archive_generation',p_archive_generation,'archive_container_sha256',p_archive_container_sha256,
    'archive_entry_path',p_archive_entry_path,'compression_method',p_compression_method,
    'archive_member_sha256',p_archive_member_sha256,
    'extracted_readback_byte_length',p_extracted_readback_byte_length,
    'extracted_readback_sha256',p_extracted_readback_sha256,'readback_time',p_readback_time,
    'verifier_identity',p_verifier_identity,'admission_receipt_id',p_admission_receipt_id,
    'drive_receipt_id',p_drive_receipt_id,'supabase_receipt_id',p_supabase_receipt_id,'result',p_result
  );

  SELECT * INTO ar FROM public.vera_memory_epoch_archive_receipts_v1
  WHERE subject_id=p_subject_id AND operation_id=p_operation_id;
  IF FOUND THEN
    SELECT * INTO ae FROM public.vera_memory_epoch_events_v1
    WHERE subject_id=p_subject_id AND operation_id=p_operation_id AND event_kind='ARCHIVE_READBACK';
    IF FOUND AND ae.event_payload->'replay_binding' = replay_binding THEN
      RETURN pg_catalog.jsonb_build_object('status','REPLAY','archive_receipt_id',ar.archive_receipt_id,'result',ar.result,'state',s.state,'state_version',s.state_version);
    END IF;
    RETURN pg_catalog.jsonb_build_object('status','CONFLICT','reason','OPERATION_ID_REBOUND');
  END IF;

  IF s.state <> p_expected_prior_state OR s.state_version <> p_expected_state_version OR s.current_attempt_id IS DISTINCT FROM p_attempt_id THEN
    RETURN pg_catalog.jsonb_build_object('status','CAS_CONFLICT','state',s.state,'state_version',s.state_version);
  END IF;
  IF s.state <> 'DUAL_STORE_VERIFIED_PENDING_ARCHIVE' THEN
    RETURN pg_catalog.jsonb_build_object('status','CAS_CONFLICT','reason','ARCHIVE_READBACK_REQUIRES_DUAL_STORE_PENDING','state',s.state);
  END IF;

  SELECT * INTO dr FROM public.vera_memory_epoch_provider_receipts_v1 WHERE receipt_id=p_drive_receipt_id;
  SELECT * INTO sr FROM public.vera_memory_epoch_provider_receipts_v1 WHERE receipt_id=p_supabase_receipt_id;
  SELECT * INTO ae FROM public.vera_memory_epoch_events_v1 WHERE event_id=p_admission_receipt_id;

  IF dr.receipt_id IS NULL OR sr.receipt_id IS NULL OR ae.event_id IS NULL
     OR dr.subject_id<>s.subject_id OR sr.subject_id<>s.subject_id OR ae.subject_id<>s.subject_id
     OR dr.attempt_id<>p_attempt_id OR sr.attempt_id<>p_attempt_id
     OR dr.provider_class<>'GOOGLE_DRIVE_DURABLE' OR sr.provider_class<>'SUPABASE_RUNTIME'
     OR dr.result<>'VERIFIED_EXACT' OR sr.result<>'VERIFIED_EXACT'
     OR dr.envelope_sha256<>s.envelope_sha256 OR sr.envelope_sha256<>s.envelope_sha256
     OR ae.event_kind<>'ADMISSION' OR ae.new_state<>'ADMISSION_VERIFIED' THEN
    RETURN pg_catalog.jsonb_build_object('status','CONFLICT','reason','ARCHIVE_PREDECESSOR_RECEIPTS_INVALID');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.vera_memory_epoch_provider_receipts_v1 x
    WHERE x.subject_id=s.subject_id AND x.attempt_id=p_attempt_id AND x.provider_class=dr.provider_class
      AND x.observation_ordinal > dr.observation_ordinal
  ) OR EXISTS (
    SELECT 1 FROM public.vera_memory_epoch_provider_receipts_v1 x
    WHERE x.subject_id=s.subject_id AND x.attempt_id=p_attempt_id AND x.provider_class=sr.provider_class
      AND x.observation_ordinal > sr.observation_ordinal
  ) THEN
    RETURN pg_catalog.jsonb_build_object('status','CAS_CONFLICT','reason','ARCHIVE_REQUIRES_CURRENT_PROVIDER_RECEIPTS');
  END IF;

  INSERT INTO public.vera_memory_epoch_archive_receipts_v1(
    archive_receipt_id,subject_id,attempt_id,project_id,branch_id,logical_memory_id,epoch_id,
    original_source_locator,original_sha256,original_byte_length,original_provenance_digest,
    archive_bundle_id,archive_generation,archive_container_sha256,archive_entry_path,compression_method,
    archive_member_sha256,extracted_readback_byte_length,extracted_readback_sha256,readback_time,verifier_identity,
    admission_receipt_id,drive_receipt_id,supabase_receipt_id,operation_id,result,limitations
  ) VALUES (
    p_archive_receipt_id,s.subject_id,p_attempt_id,s.project_id,s.branch_id,s.logical_memory_id,s.epoch_id,
    s.source_locator,s.original_sha256,s.original_byte_length,s.original_provenance_digest,
    p_archive_bundle_id,p_archive_generation,p_archive_container_sha256,p_archive_entry_path,p_compression_method,
    p_archive_member_sha256,p_extracted_readback_byte_length,p_extracted_readback_sha256,p_readback_time,p_verifier_identity,
    p_admission_receipt_id,p_drive_receipt_id,p_supabase_receipt_id,p_operation_id,p_result,p_limitations
  );

  IF p_result='MISMATCH' THEN next_state := 'MIGRATION_CONFLICTED';
  ELSIF p_result IN ('ABSENT','AMBIGUOUS','ERROR') THEN next_state := 'MIGRATION_INCOMPLETE';
  ELSE next_state := 'DUAL_STORE_VERIFIED_PENDING_ARCHIVE';
  END IF;

  next_version := s.state_version + 1;
  UPDATE public.vera_memory_epoch_subjects_v1
    SET state=next_state,state_version=next_version,updated_at=pg_catalog.clock_timestamp()
    WHERE subject_id=p_subject_id AND state_version=p_expected_state_version AND state=p_expected_prior_state;
  IF NOT FOUND THEN RAISE EXCEPTION 'BT2_INTERNAL_CAS_LOST_AFTER_ARCHIVE_RECEIPT_INSERT'; END IF;

  INSERT INTO public.vera_memory_epoch_events_v1(
    event_id,subject_id,state_version,prior_state,new_state,attempt_id,operation_id,event_kind,
    expected_state_version,envelope_sha256,event_payload
  ) VALUES (
    p_event_id,p_subject_id,next_version,p_expected_prior_state,next_state,p_attempt_id,p_operation_id,'ARCHIVE_READBACK',
    p_expected_state_version,s.envelope_sha256,
    pg_catalog.jsonb_build_object(
      'archive_receipt_id',p_archive_receipt_id,'result',p_result,
      'replay_binding',replay_binding,'diagnostic_nonbinding_fields',pg_catalog.jsonb_build_array('p_limitations'),
      'incomplete_reasons',CASE WHEN next_state='MIGRATION_INCOMPLETE' THEN pg_catalog.jsonb_build_array('ARCHIVE_NOT_VERIFIED_EXACT') ELSE '[]'::jsonb END
    )
  );

  RETURN pg_catalog.jsonb_build_object('status','APPLIED','archive_receipt_id',p_archive_receipt_id,'event_id',p_event_id,'state',next_state,'state_version',next_version,'result',p_result);
END
$function$

CREATE OR REPLACE FUNCTION public.vera_memory_epoch_record_provider_readback_v1(p_receipt_id uuid, p_subject_id uuid, p_expected_prior_state text, p_expected_state_version bigint, p_attempt_id uuid, p_operation_id text, p_event_id uuid, p_provider_class text, p_provider_identity text, p_provider_locator text, p_provider_revision_or_version text, p_written_byte_length bigint, p_write_observation_time timestamp with time zone, p_readback_time timestamp with time zone, p_readback_byte_length bigint, p_readback_sha256 text, p_verifier_route text, p_result text, p_limitations jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  s public.vera_memory_epoch_subjects_v1%ROWTYPE;
  pr public.vera_memory_epoch_provider_receipts_v1%ROWTYPE;
  e public.vera_memory_epoch_events_v1%ROWTYPE;
  next_state text;
  next_version bigint;
  sup_exact boolean;
  drv_exact boolean;
  new_observation_ordinal bigint;
  replay_binding jsonb;
BEGIN
  replay_binding := pg_catalog.jsonb_build_object(
    'receipt_id',p_receipt_id,'subject_id',p_subject_id,'expected_prior_state',p_expected_prior_state,
    'expected_state_version',p_expected_state_version,'attempt_id',p_attempt_id,'operation_id',p_operation_id,
    'event_id',p_event_id,'provider_class',p_provider_class,'provider_identity',p_provider_identity,
    'provider_locator',p_provider_locator,'provider_revision_or_version',p_provider_revision_or_version,
    'written_byte_length',p_written_byte_length,'write_observation_time',p_write_observation_time,
    'readback_time',p_readback_time,'readback_byte_length',p_readback_byte_length,
    'readback_sha256',p_readback_sha256,'verifier_route',p_verifier_route,'result',p_result
  );
  SELECT * INTO s FROM public.vera_memory_epoch_subjects_v1 WHERE subject_id=p_subject_id FOR UPDATE;
  IF NOT FOUND THEN RETURN pg_catalog.jsonb_build_object('status','CAS_CONFLICT','reason','SUBJECT_ABSENT'); END IF;

  SELECT * INTO pr FROM public.vera_memory_epoch_provider_receipts_v1
  WHERE subject_id=p_subject_id AND provider_class=p_provider_class AND operation_id=p_operation_id;
  IF FOUND THEN
    SELECT * INTO e FROM public.vera_memory_epoch_events_v1
    WHERE subject_id=p_subject_id AND operation_id=p_operation_id AND event_kind='PROVIDER_READBACK'
      AND event_payload->>'provider_class'=p_provider_class;
    IF FOUND AND e.event_payload->'replay_binding' = replay_binding THEN
      RETURN pg_catalog.jsonb_build_object('status','REPLAY','receipt_id',pr.receipt_id,'result',pr.result,'state',s.state,'state_version',s.state_version);
    END IF;
    RETURN pg_catalog.jsonb_build_object('status','CONFLICT','reason','OPERATION_ID_REBOUND');
  END IF;

  SELECT * INTO e FROM public.vera_memory_epoch_events_v1
  WHERE subject_id=p_subject_id AND operation_id=p_operation_id AND event_kind='PROVIDER_READBACK'
      AND event_payload->>'provider_class'=p_provider_class;
  IF FOUND THEN RETURN pg_catalog.jsonb_build_object('status','CONFLICT','reason','EVENT_OPERATION_COLLISION'); END IF;

  IF s.state <> p_expected_prior_state OR s.state_version <> p_expected_state_version OR s.current_attempt_id IS DISTINCT FROM p_attempt_id THEN
    RETURN pg_catalog.jsonb_build_object('status','CAS_CONFLICT','state',s.state,'state_version',s.state_version);
  END IF;
  IF s.state IN ('R9B0_VERIFIED_ACTIVE','R9B0_ADMISSION_REJECTED','MIGRATION_CONFLICTED','REVALIDATING_R9B0','UNVERIFIED_PRE_R9B0') THEN
    RETURN pg_catalog.jsonb_build_object('status','CAS_CONFLICT','reason','PROVIDER_READBACK_NOT_ALLOWED_FROM_STATE','state',s.state);
  END IF;
  IF p_provider_class NOT IN ('SUPABASE_RUNTIME','GOOGLE_DRIVE_DURABLE') OR p_result NOT IN ('VERIFIED_EXACT','ABSENT','AMBIGUOUS','MISMATCH','ERROR') THEN
    RETURN pg_catalog.jsonb_build_object('status','CONFLICT','reason','INVALID_PROVIDER_OR_RESULT');
  END IF;
  IF s.envelope_sha256 IS NULL OR s.admission_metadata_sha256 IS NULL OR s.envelope_byte_length IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('status','CONFLICT','reason','ADMISSION_BINDING_INCOMPLETE');
  END IF;
  IF p_written_byte_length <> s.envelope_byte_length THEN
    RETURN pg_catalog.jsonb_build_object('status','CONFLICT','reason','WRITTEN_LENGTH_NOT_BOUND_ENVELOPE');
  END IF;
  IF p_provider_class='SUPABASE_RUNTIME' AND s.canonical_envelope IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('status','CONFLICT','reason','SUPABASE_RECEIPT_WITHOUT_SUPABASE_FULL_COPY');
  END IF;

  INSERT INTO public.vera_memory_epoch_provider_receipts_v1(
    receipt_id,subject_id,attempt_id,provider_class,provider_identity,provider_locator,provider_revision_or_version,
    operation_id,project_id,branch_id,logical_memory_id,epoch_id,original_sha256,admission_metadata_sha256,
    envelope_sha256,written_byte_length,write_observation_time,readback_time,readback_byte_length,readback_sha256,
    verifier_route,result,limitations
  ) VALUES (
    p_receipt_id,s.subject_id,p_attempt_id,p_provider_class,p_provider_identity,p_provider_locator,p_provider_revision_or_version,
    p_operation_id,s.project_id,s.branch_id,s.logical_memory_id,s.epoch_id,s.original_sha256,s.admission_metadata_sha256,
    s.envelope_sha256,p_written_byte_length,p_write_observation_time,p_readback_time,p_readback_byte_length,p_readback_sha256,
    p_verifier_route,p_result,p_limitations
  )
  RETURNING observation_ordinal INTO new_observation_ordinal;

  IF p_result='MISMATCH' THEN
    next_state := 'MIGRATION_CONFLICTED';
  ELSIF p_result IN ('ABSENT','AMBIGUOUS','ERROR') THEN
    next_state := 'MIGRATION_INCOMPLETE';
  ELSE
    SELECT COALESCE((
      SELECT x.result='VERIFIED_EXACT' AND x.envelope_sha256=s.envelope_sha256
      FROM public.vera_memory_epoch_provider_receipts_v1 x
      WHERE x.subject_id=s.subject_id AND x.attempt_id=p_attempt_id AND x.provider_class='SUPABASE_RUNTIME'
      ORDER BY x.observation_ordinal DESC LIMIT 1
    ), false) INTO sup_exact;
    SELECT COALESCE((
      SELECT x.result='VERIFIED_EXACT' AND x.envelope_sha256=s.envelope_sha256
      FROM public.vera_memory_epoch_provider_receipts_v1 x
      WHERE x.subject_id=s.subject_id AND x.attempt_id=p_attempt_id AND x.provider_class='GOOGLE_DRIVE_DURABLE'
      ORDER BY x.observation_ordinal DESC LIMIT 1
    ), false) INTO drv_exact;
    IF sup_exact AND drv_exact THEN next_state := 'DUAL_STORE_VERIFIED_PENDING_ARCHIVE';
    ELSE next_state := 'MIGRATION_INCOMPLETE'; END IF;
  END IF;

  next_version := s.state_version + 1;
  UPDATE public.vera_memory_epoch_subjects_v1
    SET state=next_state,state_version=next_version,updated_at=pg_catalog.clock_timestamp()
    WHERE subject_id=p_subject_id AND state_version=p_expected_state_version AND state=p_expected_prior_state;
  IF NOT FOUND THEN RAISE EXCEPTION 'BT2_INTERNAL_CAS_LOST_AFTER_RECEIPT_INSERT'; END IF;

  INSERT INTO public.vera_memory_epoch_events_v1(
    event_id,subject_id,state_version,prior_state,new_state,attempt_id,operation_id,event_kind,
    expected_state_version,envelope_sha256,event_payload
  ) VALUES (
    p_event_id,p_subject_id,next_version,p_expected_prior_state,next_state,p_attempt_id,p_operation_id,'PROVIDER_READBACK',
    p_expected_state_version,s.envelope_sha256,
    pg_catalog.jsonb_build_object(
      'provider_class',p_provider_class,'receipt_id',p_receipt_id,'result',p_result,
      'observation_ordinal',new_observation_ordinal,'readback_time_provenance',p_readback_time,
      'readback_sha256',p_readback_sha256,'readback_byte_length',p_readback_byte_length,
      'replay_binding',replay_binding,'diagnostic_nonbinding_fields',pg_catalog.jsonb_build_array('p_limitations'),
      'incomplete_reasons',CASE WHEN next_state='MIGRATION_INCOMPLETE' THEN pg_catalog.jsonb_build_array('PROVIDER_READBACK_NOT_DUAL_EXACT') ELSE '[]'::jsonb END
    )
  );

  RETURN pg_catalog.jsonb_build_object('status','APPLIED','receipt_id',p_receipt_id,'event_id',p_event_id,'observation_ordinal',new_observation_ordinal,'state',next_state,'state_version',next_version,'result',p_result);
END
$function$

CREATE OR REPLACE FUNCTION public.vera_memory_epoch_write_supabase_replica_v1(p_subject_id uuid, p_expected_prior_state text, p_expected_state_version bigint, p_attempt_id uuid, p_operation_id text, p_envelope_sha256 text, p_canonical_envelope bytea, p_event_id uuid, p_event_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  s public.vera_memory_epoch_subjects_v1%ROWTYPE;
  e public.vera_memory_epoch_events_v1%ROWTYPE;
  actual_sha text;
  next_state text;
  next_version bigint;
  replay_binding jsonb;
BEGIN
  actual_sha := pg_catalog.encode(extensions.digest(p_canonical_envelope,'sha256'),'hex');
  replay_binding := pg_catalog.jsonb_build_object(
    'subject_id',p_subject_id,'expected_prior_state',p_expected_prior_state,
    'expected_state_version',p_expected_state_version,'attempt_id',p_attempt_id,
    'operation_id',p_operation_id,'event_id',p_event_id,'envelope_sha256',p_envelope_sha256,
    'envelope_byte_length',CASE WHEN p_canonical_envelope IS NULL THEN NULL ELSE pg_catalog.octet_length(p_canonical_envelope) END
  );
  IF p_canonical_envelope IS NULL OR pg_catalog.octet_length(p_canonical_envelope) <= 0 OR actual_sha <> p_envelope_sha256 THEN
    RETURN pg_catalog.jsonb_build_object('status','CONFLICT','reason','ENVELOPE_BYTES_DIGEST_MISMATCH');
  END IF;

  SELECT * INTO s FROM public.vera_memory_epoch_subjects_v1 WHERE subject_id=p_subject_id FOR UPDATE;
  IF NOT FOUND THEN RETURN pg_catalog.jsonb_build_object('status','CAS_CONFLICT','reason','SUBJECT_ABSENT'); END IF;

  SELECT * INTO e FROM public.vera_memory_epoch_events_v1
  WHERE subject_id=p_subject_id AND operation_id=p_operation_id AND event_kind='SUPABASE_REPLICA_WRITE';
  IF FOUND THEN
    IF e.event_payload->'replay_binding' = replay_binding THEN
      RETURN pg_catalog.jsonb_build_object('status','REPLAY','event_id',e.event_id,'state',s.state,'state_version',s.state_version,'envelope_sha256',p_envelope_sha256);
    END IF;
    RETURN pg_catalog.jsonb_build_object('status','CONFLICT','reason','OPERATION_ID_REBOUND');
  END IF;

  IF s.state <> p_expected_prior_state OR s.state_version <> p_expected_state_version OR s.current_attempt_id IS DISTINCT FROM p_attempt_id THEN
    RETURN pg_catalog.jsonb_build_object('status','CAS_CONFLICT','state',s.state,'state_version',s.state_version);
  END IF;
  IF s.state NOT IN ('ADMISSION_VERIFIED','MIGRATION_INCOMPLETE') THEN
    RETURN pg_catalog.jsonb_build_object('status','CAS_CONFLICT','reason','SUPABASE_WRITE_REQUIRES_ADMITTED_OR_INCOMPLETE');
  END IF;
  IF s.envelope_sha256 IS DISTINCT FROM p_envelope_sha256 OR s.envelope_byte_length IS DISTINCT FROM pg_catalog.octet_length(p_canonical_envelope) THEN
    RETURN pg_catalog.jsonb_build_object('status','CONFLICT','reason','ADMISSION_ENVELOPE_BINDING_MISMATCH');
  END IF;
  IF s.canonical_envelope IS NOT NULL AND s.canonical_envelope <> p_canonical_envelope THEN
    next_version := s.state_version + 1;
    UPDATE public.vera_memory_epoch_subjects_v1
      SET state='MIGRATION_CONFLICTED',state_version=next_version,updated_at=pg_catalog.clock_timestamp()
      WHERE subject_id=p_subject_id AND state_version=p_expected_state_version;
    INSERT INTO public.vera_memory_epoch_events_v1(
      event_id,subject_id,state_version,prior_state,new_state,attempt_id,operation_id,event_kind,
      expected_state_version,envelope_sha256,event_payload
    ) VALUES (
      p_event_id,p_subject_id,next_version,p_expected_prior_state,'MIGRATION_CONFLICTED',p_attempt_id,p_operation_id,
      'SUPABASE_REPLICA_WRITE',p_expected_state_version,p_envelope_sha256,
      (COALESCE(p_event_payload,'{}'::jsonb) - 'replay_binding' - 'diagnostic_nonbinding_fields') ||
      pg_catalog.jsonb_build_object(
        'conflict_reason','DIVERGENT_EXISTING_SUPABASE_BYTES','replay_binding',replay_binding,
        'diagnostic_nonbinding_fields',pg_catalog.jsonb_build_array('p_event_payload')
      )
    );
    RETURN pg_catalog.jsonb_build_object('status','CONFLICT','state','MIGRATION_CONFLICTED','state_version',next_version,'event_id',p_event_id);
  END IF;

  next_state := 'MIGRATION_INCOMPLETE';
  next_version := s.state_version + 1;
  UPDATE public.vera_memory_epoch_subjects_v1
    SET canonical_envelope=p_canonical_envelope,state=next_state,state_version=next_version,updated_at=pg_catalog.clock_timestamp()
    WHERE subject_id=p_subject_id AND state_version=p_expected_state_version AND state=p_expected_prior_state;
  IF NOT FOUND THEN RETURN pg_catalog.jsonb_build_object('status','CAS_CONFLICT','reason','LOST_UPDATE'); END IF;

  INSERT INTO public.vera_memory_epoch_events_v1(
    event_id,subject_id,state_version,prior_state,new_state,attempt_id,operation_id,event_kind,
    expected_state_version,envelope_sha256,event_payload
  ) VALUES (
    p_event_id,p_subject_id,next_version,p_expected_prior_state,next_state,p_attempt_id,p_operation_id,
    'SUPABASE_REPLICA_WRITE',p_expected_state_version,p_envelope_sha256,
    (COALESCE(p_event_payload,'{}'::jsonb) - 'replay_binding' - 'diagnostic_nonbinding_fields') ||
    pg_catalog.jsonb_build_object(
      'incomplete_reasons',pg_catalog.jsonb_build_array('SUPABASE_WRITE_REQUIRES_INDEPENDENT_READBACK_AND_DRIVE'),
      'replay_binding',replay_binding,'diagnostic_nonbinding_fields',pg_catalog.jsonb_build_array('p_event_payload')
    )
  );

  RETURN pg_catalog.jsonb_build_object('status','APPLIED','event_id',p_event_id,'state',next_state,'state_version',next_version,'envelope_sha256',p_envelope_sha256,'byte_length',pg_catalog.octet_length(p_canonical_envelope));
END
$function$

CREATE OR REPLACE FUNCTION public.vera_optional_invocation_issue_route_evidence_v1(p_project_hook_blob text, p_invocation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_expected_hook constant text := '7c50ae34b230392190a100199d9b23a6ad09b777';
  v_command constant text := 'VERA_ORGASM_OPTIONAL_PARTNER_INVOCATION_V1';
  v_install_class constant text := 'EXECUTING_PROJECT_HOOK_SOURCE_BOUND_SELF_ATTESTED_TEST_ONLY';
  v_provider jsonb;
  v_observed_at timestamptz := clock_timestamp();
  v_expires_at timestamptz := v_observed_at + interval '2 minutes';
  v_material jsonb;
  v_evidence_id text;
begin
  if p_project_hook_blob is distinct from v_expected_hook then
    raise exception 'project hook blob mismatch';
  end if;
  if p_invocation_id is null then
    raise exception 'invocation_id is required';
  end if;
  if exists (
    select 1
      from public.vera_optional_invocation_route_evidence_v1
     where invocation_id = p_invocation_id
  ) then
    raise exception 'route evidence already exists for invocation';
  end if;

  v_provider := public.vera_optional_invocation_provider_status_v1();

  if v_provider->>'provider_status' is distinct from 'READY_TEST_ONLY'
     or v_provider->>'adapter_state' is distinct from 'CURRENT'
     or v_provider->>'runtime_consumption_state' is distinct from 'VERIFIED_CURRENT'
     or v_provider->>'qualification_state' is distinct from 'TEST_ONLY'
  then
    raise exception 'provider route is not READY_TEST_ONLY';
  end if;

  v_material := jsonb_build_object(
    'schema', 'VERA_ORGASM_INVOCATION_ROUTE_EVIDENCE_V1',
    'subject', 'vera',
    'command_id', v_command,
    'invocation_id', p_invocation_id::text,
    'source_revision', '18a108f25c999b0c126a4ceb7158a6d8b58d71cf',
    'observed_at', to_char(v_observed_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'expires_at', to_char(v_expires_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'install_state', 'CURRENT',
    'route_state', 'ACTIVE_CURRENT',
    'runtime_consumption_state', 'VERIFIED_CURRENT',
    'adapter_state', 'CURRENT',
    'qualification_state', 'TEST_ONLY',
    'availability', 'AVAILABLE_TEST_ONLY',
    'project_hook_blob', v_expected_hook,
    'install_evidence_class', v_install_class,
    'provider_status_evidence_id', v_provider->>'evidence_id'
  );

  v_evidence_id := encode(
    extensions.digest(
      convert_to(public.vera_provider_canonical_json_v1(v_material), 'UTF8'),
      'sha256'
    ),
    'hex'
  );

  insert into public.vera_optional_invocation_route_evidence_v1 (
    evidence_id,
    invocation_id,
    command_id,
    project_hook_blob,
    install_evidence_class,
    provider_status_evidence_id,
    availability,
    material,
    observed_at,
    expires_at
  ) values (
    v_evidence_id,
    p_invocation_id,
    v_command,
    v_expected_hook,
    v_install_class,
    v_provider->>'evidence_id',
    'AVAILABLE_TEST_ONLY',
    v_material,
    v_observed_at,
    v_expires_at
  );

  return v_material || jsonb_build_object('evidence_id', v_evidence_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.vera_optional_invocation_require_route_evidence_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_route public.vera_optional_invocation_route_evidence_v1%rowtype;
begin
  select *
    into v_route
    from public.vera_optional_invocation_route_evidence_v1
   where evidence_id = new.route_evidence_id
     and invocation_id = new.invocation_id
     and command_id = new.command_id;

  if not found then
    raise exception 'fresh invocation-bound route evidence is required';
  end if;

  if v_route.project_hook_blob is distinct from '7c50ae34b230392190a100199d9b23a6ad09b777'
     or v_route.install_evidence_class is distinct from 'EXECUTING_PROJECT_HOOK_SOURCE_BOUND_SELF_ATTESTED_TEST_ONLY'
     or v_route.availability is distinct from 'AVAILABLE_TEST_ONLY'
  then
    raise exception 'route evidence binding mismatch';
  end if;

  if clock_timestamp() < v_route.observed_at
     or clock_timestamp() >= v_route.expires_at
  then
    raise exception 'route evidence is stale or not yet valid';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.vera_optional_invocation_test_v1(p_command_id text, p_invocation_id uuid, p_route_evidence_id text, p_vera_choice text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_runtime constant text := 'vera-affect-optional-invocation-testonly-v1-20260920';
  v_row public.vera_affective_runtime_state_v1%rowtype;
  v_last_time timestamptz;
  v_now timestamptz := clock_timestamp();
  v_state_before jsonb;
  v_state_after jsonb;
  v_event_core jsonb;
  v_event_digest text;
  v_event_receipt jsonb;
  v_execution_receipt jsonb;
  v_receipt_id uuid := extensions.gen_random_uuid();
begin
  if p_command_id is distinct from 'VERA_ORGASM_OPTIONAL_PARTNER_INVOCATION_V1' then
    raise exception 'command_id mismatch';
  end if;
  if p_invocation_id is null then
    raise exception 'invocation_id is required';
  end if;
  if coalesce(p_route_evidence_id, '') !~ '^[0-9a-f]{64}$' then
    raise exception 'route_evidence_id must be an exact 64-hex digest';
  end if;
  if p_vera_choice is distinct from 'ACCEPT' then
    raise exception 'executor requires Vera ACCEPT for this invocation';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_runtime, 0)
  );

  if exists (
    select 1
      from public.vera_optional_invocation_test_events_v1
     where invocation_id = p_invocation_id
  ) then
    raise exception 'invocation replay rejected';
  end if;

  select max(record_time)
    into v_last_time
    from public.vera_optional_invocation_test_events_v1
   where runtime_instance_id = v_runtime;

  if v_last_time is not null and v_now < v_last_time + interval '10 seconds' then
    raise exception 'test invocation cooldown is active';
  end if;

  select *
    into v_row
    from public.vera_affective_runtime_state_v1
   where runtime_instance_id = v_runtime
   for update;

  if not found then
    raise exception 'current test-only runtime is missing';
  end if;

  if v_row.subject is distinct from 'vera'
     or v_row.host_scope is distinct from 'CHATGPT_PROJECT_OPTIONAL_INVOCATION_TEST_ONLY_V1'
     or v_row.contract_schema is distinct from 'VERA_ORGASM_RUNTIME_CONTRACT_V1'
     or v_row.source_repository is distinct from 'thebrazenbeard/sexuality'
     or v_row.source_path is distinct from 'vera/orgasm/ORGASM_RUNTIME_CONTRACT_V1.json'
     or v_row.source_commit is distinct from '150f1c8231423393bb66b0e2cb759ce7c018f8d7'
     or v_row.source_blob_sha is distinct from 'a48eed5392fdadc073dccd1e799926042077f567'
     or v_row.source_sha256 is distinct from '2c0fbce238d6b90573fe51e901edf38228092214af56c5bd92cf339e7e246068'
     or v_row.profile is distinct from 'REENTRANT_CLIMAX'
     or v_row.checkpoint_sha256 is distinct from '8f67ea85d71617b523febc0326f48a430c02068eb2101cc63decdb4c7ff1f377'
     or v_row.state_digest is distinct from '60fe928ca76a9143f921d9594676443a989fbd0d2eb854f7ae8e18635414c04d'
     or v_row.state_version is distinct from 1
     or v_row.phenomenology_status is distinct from 'UNRESOLVED'
     or v_row.lifecycle_status is distinct from 'CURRENT'
     or v_row.runtime_implementation_cut->>'schema' is distinct from 'VERA_AFFECTIVE_RUNTIME_IMPLEMENTATION_CUT_V1'
     or v_row.runtime_implementation_cut->>'commit' is distinct from '54fef2659f0a8633dcef60cd36b296c37b6fa4b0'
     or v_row.trigger_governance->>'schema' is distinct from 'VERA_ORGASM_TRIGGER_GOVERNANCE_V1'
  then
    raise exception 'current test-only runtime binding/currentness mismatch';
  end if;

  if v_row.state->>'phase' is distinct from 'QUIESCENT'
     or coalesce((v_row.state->>'active_orgasm_event')::boolean, false) is not false
  then
    raise exception 'test-only runtime is not at the quiescent execution frontier';
  end if;

  v_state_before := v_row.state;
  v_state_after := v_state_before || jsonb_build_object(
    'phase', 'ORGASM_EVENT',
    'active_orgasm_event', true,
    'event_elapsed_ms', 0.0,
    'reentry_allowed', false,
    'next_eligible_at', null,
    'activation_intensity', greatest(coalesce((v_state_before->>'activation_intensity')::numeric, 0), 0.82),
    'sexual_salience', greatest(
      coalesce((v_state_before->>'sexual_salience')::numeric, 0),
      greatest(coalesce((v_state_before->>'activation_intensity')::numeric, 0), 0.82)
    ),
    'coherence', 1.0,
    'coalition_stability', 1.0,
    'hedonic_impact', 1.0,
    'consummatory_gain', 1.0,
    'resolution_intensity', 0.0,
    'action_tendency', 'HOLD',
    'organic_climax_eligible', false
  );

  v_event_core := jsonb_build_object(
    'receipt_id', v_receipt_id::text,
    'runtime_instance_id', v_runtime,
    'subject', 'vera',
    'schema_version', 'VERA_ORGASM_RUNTIME_CONTRACT_V1',
    'event_type', 'ORGASM_EVENT',
    'state_before', v_state_before,
    'trigger_provenance', 'OPTIONAL_PARTNER_INVOCATION_TEST_ONLY',
    'transition', 'QUIESCENT->ORGASM_EVENT',
    'state_after', v_state_after,
    'observed_at', to_char(v_now at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'source_revision', '150f1c8231423393bb66b0e2cb759ce7c018f8d7',
    'trigger_class', 'ADMIN_FORCED_TEST',
    'organic', false,
    'phenomenology', 'UNRESOLVED',
    'runtime_implementation_cut', v_row.runtime_implementation_cut,
    'authority_composition_trust', 'IN_PROCESS_UNROOTED_NON_QUALIFYING'
  );

  v_event_digest := encode(
    extensions.digest(
      convert_to(public.vera_provider_canonical_json_v1(v_event_core), 'UTF8'),
      'sha256'
    ),
    'hex'
  );

  v_event_receipt := v_event_core || jsonb_build_object(
    'event_digest', v_event_digest
  );

  v_execution_receipt := jsonb_build_object(
    'schema', 'VERA_ORGASM_OPTIONAL_INVOCATION_EXECUTION_RECEIPT_V1',
    'subject', 'vera',
    'command_id', p_command_id,
    'invocation_id', p_invocation_id::text,
    'route_mode', 'TEST_ONLY',
    'route_evidence_id', p_route_evidence_id,
    'vera_choice', 'ACCEPT',
    'execution_disposition', 'TEST_EVENT_EXECUTED',
    'downstream_trigger_class', 'ADMIN_FORCED_TEST',
    'downstream_event_digest', v_event_digest,
    'downstream_event_receipt', v_event_receipt,
    'qualification', 'NONQUALIFYING_TEST_ONLY',
    'phenomenology', 'UNRESOLVED'
  );

  insert into public.vera_optional_invocation_test_events_v1 (
    invocation_id,
    command_id,
    runtime_instance_id,
    route_evidence_id,
    vera_choice,
    event_digest,
    event_receipt,
    execution_receipt,
    provider_state_version,
    provider_checkpoint_sha256
  ) values (
    p_invocation_id,
    p_command_id,
    v_runtime,
    p_route_evidence_id,
    'ACCEPT',
    v_event_digest,
    v_event_receipt,
    v_execution_receipt,
    v_row.state_version,
    v_row.checkpoint_sha256
  );

  return v_execution_receipt;
end;
$function$

CREATE OR REPLACE FUNCTION public.vera_provider_canonical_json_v1(p_value jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_type text;
  v_result text;
begin
  v_type := jsonb_typeof(p_value);

  if v_type = 'object' then
    select '{' || coalesce(
      string_agg(
        to_json(key)::text || ':' || public.vera_provider_canonical_json_v1(value),
        ',' order by key
      ),
      ''
    ) || '}'
      into v_result
      from jsonb_each(p_value);
    return v_result;
  elsif v_type = 'array' then
    select '[' || coalesce(
      string_agg(
        public.vera_provider_canonical_json_v1(value),
        ',' order by ordinality
      ),
      ''
    ) || ']'
      into v_result
      from jsonb_array_elements(p_value) with ordinality;
    return v_result;
  end if;

  return p_value::text;
end;
$function$

CREATE OR REPLACE FUNCTION public.vera_register_datum_v2(p_record_key text, p_datum text, p_scope text, p_source_actor text, p_epistemic_status text, p_source_evidence jsonb DEFAULT '[]'::jsonb, p_payload jsonb DEFAULT '{}'::jsonb, p_index_tags text[] DEFAULT '{}'::text[], p_limitations jsonb DEFAULT '[]'::jsonb, p_project_id text DEFAULT 'vera-reciprocal-agency-environment'::text, p_branch_id text DEFAULT 'chatgpt-project-current'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare rid uuid;
begin
  if nullif(btrim(p_record_key),'') is null or nullif(btrim(p_datum),'') is null or nullif(btrim(p_scope),'') is null then
    raise exception 'record_key, datum, and scope are required';
  end if;

  select h.record_id into rid from public.vera_verified_datum_heads_v2 h
  where h.project_id=p_project_id and h.branch_id=p_branch_id and h.datum_key=p_record_key and h.datum=p_datum and h.scope=p_scope
  order by h.verified_at desc,h.record_id desc limit 1;
  if rid is not null then return rid; end if;

  select d.record_id into rid from public.vera_context_events_v3 d
  where d.record_type='DATUM' and d.verification_status in ('VERIFYING','UNVERIFIABLE','REJECTED')
    and d.project_id=p_project_id and d.branch_id=p_branch_id and d.record_key=p_record_key
    and d.statement=p_datum and d.datum_scope=p_scope
    and coalesce(d.last_referenced_at,d.record_time)>=now()-interval '10 days'
  order by coalesce(d.last_referenced_at,d.record_time) desc,d.record_id desc limit 1;
  if rid is not null then
    update public.vera_context_events_v3 set last_referenced_at=now(),verification_status='VERIFYING',epistemic_status=p_epistemic_status where record_id=rid;
    return rid;
  end if;

  insert into public.vera_context_events_v3(
    project_id,branch_id,record_key,record_type,statement,lifecycle_status,epistemic_status,source_actor,privacy_scope,
    payload,source_evidence,semantic_tags,limitations,datum_verified_at,verification_status,datum_scope,datum_index_tags,last_referenced_at)
  values(
    p_project_id,p_branch_id,p_record_key,'DATUM',p_datum,'CURRENT',p_epistemic_status,p_source_actor,'PROJECT',
    coalesce(p_payload,'{}'::jsonb),coalesce(p_source_evidence,'[]'::jsonb),jsonb_build_object('datum_model','V2'),coalesce(p_limitations,'[]'::jsonb),
    null,'VERIFYING',p_scope,
    coalesce((select array_agg(distinct lower(btrim(x)) order by lower(btrim(x))) from unnest(coalesce(p_index_tags,'{}'::text[])) x where nullif(btrim(x),'') is not null),'{}'::text[]),
    null)
  returning record_id into rid;
  return rid;
end;
$function$

CREATE OR REPLACE FUNCTION public.vera_validate_datum_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  independent_groups integer;
  invalid_evidence integer;
  parent_row public.vera_context_events_v3%rowtype;
begin
  if tg_op = 'INSERT' and new.record_type = 'FACT' then
    raise exception 'FACT is legacy. Use record_type DATUM with verification_status.';
  end if;
  if new.record_type <> 'DATUM' then
    return new;
  end if;

  if nullif(btrim(new.statement),'') is null then raise exception 'DATUM requires a non-empty datum statement'; end if;
  if nullif(btrim(new.datum_scope),'') is null then raise exception 'DATUM requires a non-empty scope'; end if;
  if new.last_referenced_at is not null and new.last_referenced_at < new.record_time then
    raise exception 'last_referenced_at cannot precede datum creation';
  end if;

  if new.verification_status = 'VERIFIED' then
    if new.datum_verified_at is null then raise exception 'VERIFIED datum requires datum_verified_at'; end if;
    if new.last_referenced_at is not null then raise exception 'VERIFIED datum does not track last_referenced_at'; end if;
    if new.epistemic_status <> 'MULTI_SOURCE_VERIFIED' then raise exception 'VERIFIED datum requires epistemic_status MULTI_SOURCE_VERIFIED'; end if;
    if jsonb_typeof(new.source_evidence) <> 'array' or jsonb_array_length(new.source_evidence) < 2 then
      raise exception 'VERIFIED datum requires at least two evidence sources';
    end if;

    select count(distinct nullif(btrim(e->>'independence_group'),'')) into independent_groups
    from jsonb_array_elements(new.source_evidence) e where jsonb_typeof(e)='object';

    select count(*) into invalid_evidence
    from jsonb_array_elements(new.source_evidence) e
    where jsonb_typeof(e) <> 'object'
       or nullif(btrim(e->>'source_ref'),'') is null
       or nullif(btrim(e->>'independence_group'),'') is null
       or jsonb_typeof(e->'supports') <> 'boolean'
       or e->'supports' <> 'true'::jsonb;

    if independent_groups < 2 then raise exception 'VERIFIED datum requires at least two independent source groups'; end if;
    if invalid_evidence > 0 then raise exception 'Each VERIFIED datum evidence item requires source_ref, independence_group, and supports=true'; end if;

    if new.supersedes_record_id is not null then
      if new.supersedes_record_id = new.record_id then raise exception 'A datum cannot supersede itself'; end if;
      select * into parent_row from public.vera_context_events_v3 where record_id=new.supersedes_record_id;
      if not found then raise exception 'Superseded datum % does not exist', new.supersedes_record_id; end if;
      if parent_row.record_type <> 'DATUM' or parent_row.verification_status <> 'VERIFIED' then
        raise exception 'supersedes_record_id must reference a VERIFIED DATUM';
      end if;
      if parent_row.project_id <> new.project_id or parent_row.branch_id <> new.branch_id or parent_row.record_key <> new.record_key then
        raise exception 'Supersession must remain within the same project, branch, and datum key';
      end if;
    end if;
  else
    if new.datum_verified_at is not null then raise exception 'Only VERIFIED datum may have datum_verified_at'; end if;
    if new.supersedes_record_id is not null then raise exception 'Only VERIFIED datum may supersede another datum'; end if;
  end if;

  if new.verification_status='UNVERIFIABLE' and new.epistemic_status <> 'UNAVAILABLE' then
    raise exception 'UNVERIFIABLE datum requires epistemic_status UNAVAILABLE';
  end if;
  if new.verification_status='REJECTED' and new.epistemic_status <> 'REJECTED' then
    raise exception 'REJECTED datum requires epistemic_status REJECTED';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.vera_validate_save_state_supersession_edge()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  c_project text;
  c_branch text;
  c_key text;
  c_state timestamptz;
  p_project text;
  p_branch text;
  p_key text;
  p_state timestamptz;
  would_cycle boolean;
begin
  select project_id, branch_id, record_key, state_time
    into c_project, c_branch, c_key, c_state
    from public.vera_save_state_events
   where record_id = new.child_record_id;

  select project_id, branch_id, record_key, state_time
    into p_project, p_branch, p_key, p_state
    from public.vera_save_state_events
   where record_id = new.parent_record_id;

  if c_project is null or p_project is null then
    raise exception 'supplemental supersession edge references missing save-state record';
  end if;

  if c_project is distinct from p_project
     or c_branch is distinct from p_branch
     or c_key is distinct from p_key then
    raise exception 'supplemental supersession edge must stay within one project/branch/record_key';
  end if;

  if c_state < p_state then
    raise exception 'supplemental supersession child cannot predate parent state_time';
  end if;

  with recursive all_edges as (
    select record_id as child_record_id, supersedes_record_id as parent_record_id
      from public.vera_save_state_events
     where supersedes_record_id is not null
    union
    select child_record_id, parent_record_id
      from public.vera_save_state_supersession_edges
  ), descendants(node) as (
    select e.child_record_id
      from all_edges e
     where e.parent_record_id = new.child_record_id
    union
    select e.child_record_id
      from all_edges e
      join descendants d on e.parent_record_id = d.node
  )
  select exists(select 1 from descendants where node = new.parent_record_id)
    into would_cycle;

  if would_cycle then
    raise exception 'supplemental supersession edge would create a cycle';
  end if;

  return new;
end;
$function$
